package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="sales_surcharge_role_limit") public class LimiteRecargoRol {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;@Column(name="role_id",nullable=false,updatable=false)private UUID rolId;@Column(name="max_percentage")private BigDecimal porcentajeMaximo;@Column(name="max_amount")private BigDecimal montoMaximo;@Column(nullable=false)private boolean active=true;@Column(name="created_at",insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by",updatable=false)private UUID creadoPor;@Column(name="updated_at")private OffsetDateTime actualizadoEn;@Column(name="updated_by")private UUID actualizadoPor;@Version private long version;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="role_id",insertable=false,updatable=false)private Rol rol;protected LimiteRecargoRol(){}public LimiteRecargoRol(UUID t,UUID e,UUID r,BigDecimal p,BigDecimal m,UUID u){tenantId=t;empresaId=e;rolId=r;porcentajeMaximo=p;montoMaximo=m;creadoPor=u;actualizadoPor=u;actualizadoEn=OffsetDateTime.now();}public void actualizar(BigDecimal p,BigDecimal m,boolean a,UUID u){porcentajeMaximo=p;montoMaximo=m;active=a;actualizadoPor=u;actualizadoEn=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getRolId(){return rolId;}public Rol getRol(){return rol;}public BigDecimal getPorcentajeMaximo(){return porcentajeMaximo;}public BigDecimal getMontoMaximo(){return montoMaximo;}public boolean isActivo(){return active;}public long getVersion(){return version;}}
